object NetworkClient {
    // ONE client for the whole app — pool, dispatcher, and caches live here
    val client: OkHttpClient by lazy {
        OkHttpClient.Builder()
            .connectionPool(ConnectionPool(5, 5, TimeUnit.MINUTES))
            .connectTimeout(10, TimeUnit.SECONDS)
            .build()
    }
}

// Per-feature clients SHARE the pool and dispatcher via newBuilder()
val authClient = NetworkClient.client.newBuilder()
    .addInterceptor(AuthInterceptor())
    .build()

// OkHttp's event log shows pool reuse: callStart -> connectionAcquired (from pool)
// with no connectStart, versus connectStart -> connectEnd when the pool missed.

val dispatcher = Dispatcher().apply {
    maxRequests = 32
    maxRequestsPerHost = 4
}
val client = OkHttpClient.Builder().dispatcher(dispatcher).build()

fun observe() {
    val d = client.dispatcher
    println("running=${d.runningCallsCount()} queued=${d.queuedCallsCount()}")
}

// Fire 200 requests; maxRequests + maxRequestsPerHost shape the throttle
repeat(200) { i ->
    val request = Request.Builder().url("https://example.com/item/$i").build()
    client.newCall(request).enqueue(object : Callback {
        override fun onFailure(call: Call, e: IOException) = println("fail $i")
        override fun onResponse(call: Call, response: Response) {
            response.close()
            println("ok $i")
        }
    })
}

val cache = Cache(File(context.cacheDir, "http_cache"), 10L * 1024 * 1024)
val client = OkHttpClient.Builder().cache(cache).build()

// Observe cache behavior on every response
val interceptor = Interceptor { chain ->
    val response = chain.proceed(chain.request())
    val cached = response.cacheResponse != null
    val network = response.networkResponse != null
    println("cacheHit=$cached network=$network code=${response.code}")
    response
}

val observed = client.newBuilder().addInterceptor(interceptor).build()

