// create() installs the proxy; parsing is eager, I/O is lazy
val retrofit = Retrofit.Builder()
    .baseUrl("https://api.example.com/")
    .addConverterFactory(Json.asConverterFactory("application/json".toMediaType()))
    .build()

val api: UserApi = retrofit.create(UserApi::class.java)   // proxy, no I/O yet
val user: User = api.getUser("42")                       // suspend -> CallAdapter -> OkHttpCall -> enqueue

class FlowCallAdapter<T>(
    private val call: Call<T>,
) : CallAdapter<T, Flow<T>> {
    override fun responseType(): Type = T::class.java
    override fun adapt(call: Call<T>): Flow<T> = flow {
        val response = call.await()
        emit(response)
    }
}

class FlowCallAdapterFactory : CallAdapter.Factory() {
    override fun get(returnType: Type, annotations: Array<Annotation>, retrofit: Retrofit): CallAdapter<*, *>? {
        val raw = getRawType(returnType)
        return if (raw == Flow::class.java) FlowCallAdapter<Any>(null as Call<Any>) else null
    }
}

sealed interface LoadResult<out T> {
    data class Success<T>(val data: T) : LoadResult<T>
    data class Failure(val kind: FailureKind, val detail: String? = null) : LoadResult<Nothing>
}

enum class FailureKind { Network, Http, Cancelled, Unknown }

suspend fun <T> safeCall(block: suspend () -> Response<T>): LoadResult<T> = try {
    val response = block()
    if (response.isSuccessful) {
        LoadResult.Success(response.body()!!)
    } else {
        val error = response.errorBody()?.string()
        LoadResult.Failure(FailureKind.Http, error)
    }
} catch (e: CancellationException) {
    throw e                       // never swallow cancellation
} catch (e: IOException) {
    LoadResult.Failure(FailureKind.Network, e.message)
}

// Pin the SPKI of the CA you control, plus a backup independent key
val client = OkHttpClient.Builder()
    .certificatePinner(
        CertificatePinner.Builder()
            .add("api.example.com", "sha256/AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=")
            .add("api.example.com", "sha256/BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB=")
            .build()
    )
    .build()

// Rotation flow: ship the new primary pin via remote config FIRST,
// rotate the server cert, then drop the old pin in a later release.

val client = OkHttpClient.Builder()
    .protocols(listOf(Protocol.HTTP_2, Protocol.HTTP_1_1))
    .connectionSpecs(listOf(ConnectionSpec.MODERN_TLS))
    .build()

// An EventListener shows which protocol a connection actually used:
// callStart -> dnsStart -> secureConnectStart -> connectionAcquired(Protocol.HTTP_2)
// HTTP/3 needs a QUIC client; OkHttp's h2 support is automatic over TLS via ALPN.

val client = OkHttpClient.Builder()
    .connectTimeout(10, TimeUnit.SECONDS)
    .readTimeout(10, TimeUnit.SECONDS)
    .writeTimeout(10, TimeUnit.SECONDS)
    .callTimeout(30, TimeUnit.SECONDS)   // bounds the WHOLE call incl. retries
    .build()

suspend fun <T> withRetry(maxAttempts: Int = 3, block: suspend () -> T): T {
    var attempt = 0
    while (true) {
        try {
            return block()
        } catch (e: IOException) {
            if (attempt >= maxAttempts) throw e
            val base = 1_000L shl attempt
            delay(base + Random.nextLong(base))   // exponential + full jitter
            attempt++
        }
    }
}
